import React, { useState } from 'react';

const CategoryFilters = ({ onFiltersChange, currentFilters }) => {
  const [hoveredFilter, setHoveredFilter] = useState(null);

  // Use the filters passed from parent (controlled component)
  const categories = currentFilters || {
    trending: true,   // NEW: Score >7 with 60% score + 40% volume (DEFAULT) - FIRST
    cults: false,     // RENAMED: Established coins (score ≥3.0, market cap ≥$1M) - formerly trending
    highCap: false,   // ≥$100M market cap
    midCap: false,    // ≥$5M to ≤$10M market cap
    smallCap: false,  // >$500K to <$5M market cap
    microCap: false,  // $30K to $500K market cap
    volatile: false,  // High price changes
    stable: false     // Low price changes
  };

  const handleCategoryToggle = (category) => {
    // Always switch to the clicked filter (even if it's already active)
    // This ensures the UI and data stay in sync
    const newCategories = {
      trending: false,
      cults: false,
      highCap: false,
      midCap: false,
      smallCap: false,
      microCap: false,
      volatile: false,
      stable: false,
      [category]: true // Enable only the clicked filter
    };

    console.log('Category switched to:', category, newCategories);
    onFiltersChange(newCategories);
  };

  const getTooltipContent = (key) => {
    switch (key) {
      case 'trending':
        return {
          title: '🔥 Trending Filter',
          description: 'Score ≥6.0 + Volume weighting',
          details: 'Top 50 emerging tokens with market cap ≤$10M'
        };
      case 'cults':
        return {
          title: '🏛️ Cults Filter',
          description: 'Established coins ≥$1M + Score ≥3.0',
          details: 'Top 50 proven tokens with significant market presence'
        };
      case 'highCap':
        return {
          title: '🏦 High Cap Filter',
          description: 'Market Cap ≥$100M',
          details: 'Large capitalization tokens'
        };
      case 'midCap':
        return {
          title: '🏢 Mid Cap Filter',
          description: 'Market Cap ≥$5M to ≤$10M',
          details: 'Medium-sized tokens'
        };
      case 'smallCap':
        return {
          title: '💎 Small Cap Filter',
          description: 'Market Cap >$500K to <$5M',
          details: 'Smaller market tokens'
        };
      case 'microCap':
        return {
          title: '🔍 Micro Cap Filter',
          description: 'Market Cap $30K to $500K',
          details: 'Very small market tokens'
        };
      case 'volatile':
        return {
          title: '⚡ Volatile Filter',
          description: 'Price change >5%',
          details: 'High volatility tokens'
        };
      case 'stable':
        return {
          title: '📈 Stable Filter',
          description: 'Price change ≤5%',
          details: 'Low volatility tokens'
        };
      default:
        return { title: key, description: '', details: '' };
    }
  };

  return (
    <div className="flex items-center space-x-2 relative">
      <span className="text-sm text-gray-400 mr-2">Categories:</span>
      {Object.entries(categories).map(([key, value]) => {
        const tooltipContent = getTooltipContent(key);
        return (
          <div key={key} className="relative">
            <button
              onClick={() => handleCategoryToggle(key)}
              onMouseEnter={() => setHoveredFilter(key)}
              onMouseLeave={() => setHoveredFilter(null)}
              className={`px-2 py-1 rounded text-xs font-medium transition-colors ${
                value
                  ? 'bg-solana-purple text-white'
                  : 'bg-dark-bg text-gray-400 hover:text-white border border-gray-600'
              }`}
            >
              {key === 'trending' && '🔥 Trending'}
              {key === 'cults' && '🏛️ Cults'}
              {key === 'highCap' && '🏦 High Cap'}
              {key === 'midCap' && '🏢 Mid Cap'}
              {key === 'smallCap' && '💎 Small Cap'}
              {key === 'microCap' && '🔍 Micro Cap'}
              {key === 'volatile' && '⚡ Volatile'}
              {key === 'stable' && '📈 Stable'}
            </button>

            {/* Tooltip Modal (matching BubbleMap design) */}
            {hoveredFilter === key && (
              <div className="bubble-tooltip absolute top-full left-1/2 transform -translate-x-1/2 mt-1 z-50">
                <div className="font-semibold text-white mb-1">{tooltipContent.title}</div>
                <div className="text-xs leading-tight">
                  <span className="text-gray-300">{tooltipContent.description}</span>
                  <span className="text-gray-500 mx-2">•</span>
                  <span className="text-gray-400">{tooltipContent.details}</span>
                </div>
              </div>
            )}
          </div>
        );
      })}
    </div>
  );
};

export default CategoryFilters;
